from pathlib import Path
r=Path('.');html=(r/'obfuscation/index.html').read_text(encoding='utf-8')
tests=r'''
<section style="background:white;border:3px solid #9078cd;padding:20px"><button id="selfCheck">运行本地网页版验收</button><pre id="checkReport" style="white-space:pre-wrap"></pre></section>
<script>
$('selfCheck').onclick=async()=>{let report=$('checkReport'),passed=[];report.textContent='RUNNING';try{const assert=(x,why)=>{if(!x)throw Error(why);};
assert($('encrounds').value==='1'&&$('decrounds').value==='1','default rounds');assert($('encshift').value==='1'&&$('decshift').value==='1'&&$('encformat').value==='png'&&$('decformat').value==='png'&&!$('green').checked&&!$('reduce').checked,'reference defaults');assert(!document.querySelector('details.parameters').open,'advanced settings expanded');assert(!['algorithm','automatic','key','seed','restore','detect','simulate','camera','capture','files','filepicker'].some(id=>$(id)),'removed controls remain');assert(Array.from(document.querySelectorAll('.action-row')).length===4&&Array.from(document.querySelectorAll('.action-row')).every(e=>e.children.length===3),'equal three columns');passed.push('参考默认参数、精简选项、默认收起设置、四行等宽三列按钮');
const w=37,h=19,rgba=new Uint8ClampedArray(w*h*4);for(let i=0;i<rgba.length;i++)rgba[i]=i%4===3?255:(i*73+37)%256;let input=await encode({w,h,rgba},'png',95),file=new File([input],'样本.png',{type:'image/png'});await imports([file,new File([input],'second.png',{type:'image/png'})]);assert(entries.length===2,'import');
const bitmapAPI=window.createImageBitmap;try{window.createImageBitmap=undefined;let missingMIME=new File([input],'empty-type.png');Object.defineProperty(missingMIME,'arrayBuffer',{value:undefined});let fallback=await decode(missingMIME,new Uint8Array(await readBlob(missingMIME)));assert(fallback.w===w&&fallback.h===h&&fallback.rgba.every((v,i)=>v===rgba[i]),'image/FileReader fallback');window.createImageBitmap=()=>Promise.reject(Error('simulated bitmap failure'));let rejectedBitmap=await decode(file,new Uint8Array(await readBlob(file)));assert(rejectedBitmap.rgba.every((v,i)=>v===rgba[i]),'rejected bitmap fallback');}finally{window.createImageBitmap=bitmapAPI;}assert(document.querySelectorAll('input[type=file]').length===1&&!$('picker').hasAttribute('capture'),'single native picker');checkDimensions(4032,3024);let overflow=false;try{checkDimensions(8192,8192);}catch{overflow=true;}assert(overflow,'oversized photo accepted');passed.push('单一系统选图、空 MIME、FileReader 与浏览器图片解码回退、1200 万像素尺寸接受、超限拒绝不缩放');
let orientedBlob=await (await fetch('/build/verification/web-mobile/orientation-6.jpg')).blob(),oriented=await decode(new File([orientedBlob],'photo.jpg'),new Uint8Array(await readBlob(orientedBlob)));assert(oriented.w===10&&oriented.h===20,'photo EXIF orientation');try{window.createImageBitmap=undefined;let orientedFallback=await decode(new File([orientedBlob],'photo.jpg'),new Uint8Array(await readBlob(orientedBlob)));assert(orientedFallback.w===10&&orientedFallback.h===20&&oriented.rgba.every((v,i)=>Math.abs(v-orientedFallback.rgba[i])<4),'fallback orientation');}finally{window.createImageBitmap=bitmapAPI;}passed.push('拍摄 JPEG EXIF 旋转：原生与回退解码一致');
let cross=[];for(let strength of [0,.5,1,1.5,2]){$('encshift').value=strength;$('decshift').value=strength;$('encrounds').value=$('decrounds').value=3;let item={file};await processItem(item,false);assert(item.outputWidth===w&&item.outputHeight===h,'resized');let b=new Uint8Array(await item.output.arrayBuffer());assert(new TextDecoder().decode(b.subarray(b.length-8,b.length-4))==='IEND','PNG trailing attachment');let enc=item.output;await processItem({file:new File([enc],'scrambled.png')},true).then(async out=>{let decoded=await decode(out,new Uint8Array(await out.arrayBuffer()));assert(decoded.rgba.every((x,i)=>x===rgba[i]),'pixel inverse');});let native=await (await fetch('/build/verification/cross-files/repeat-'+strength+'.png')).blob(),n={file:new File([native],'native.png')};await processItem(n,true);let result=await decode(n.output,new Uint8Array(await n.output.arrayBuffer()));assert(result.rgba.every((x,i)=>x===rgba[i]),'Windows to web inverse');cross.push({name:'web-repeated-'+strength+'.png',bytes:new Uint8Array(await enc.arrayBuffer())});}
passed.push('五个系数、三次混淆/还原：Worker/实际 Canvas PNG 逐像素还原、Windows → 网页互还原、无私有文件尾');
const transparent=new Uint8ClampedArray(rgba);for(let i=3;i<transparent.length;i+=4)transparent[i]=(i*7)%256;let alpha=await encode({w,h,rgba:transparent},'png',95),decoded=await decode(alpha,new Uint8Array(await alpha.arrayBuffer()));assert(decoded.rgba.every((v,i)=>i%4!==3||v===transparent[i]),'alpha changed');passed.push('透明 PNG Alpha 保留；RGB 取整沿用参考 Canvas 行为');
$('encformat').value='jpg';updateAlgorithmUI();assert(!$('encQualityGroup').hidden&&$('decQualityGroup').hidden,'JPEG related quality');$('encformat').value='png';updateAlgorithmUI();
let corrupt=new Uint8Array(await input.arrayBuffer());corrupt[40]^=1;let failed=false;try{await decode(new File([corrupt],'bad.png',{type:'image/png'}),corrupt);}catch{failed=true;}assert(failed,'bad CRC');passed.push('JPG 质量按需显示、损坏 PNG 拒绝');
entries.forEach((e,i)=>{e.checked=i===0;e.output=null;});await run(false,true,'checked');assert(entries[0].output&&!entries[1].output,'subset');await run(false,true,'all');assert(entries.every(e=>e.output),'all');entries.forEach(e=>e.checked=false);let outputs=entries.map(e=>e.output);await run(false,true,'checked');assert(entries.every((e,i)=>e.output===outputs[i]),'empty selection altered');passed.push('当前、勾选子集、全部与空勾选范围');
const count=entries.length,shift=$('encshift').value;english=!english;translate();assert(entries.length===count&&$('encshift').value===shift,'language state');english=!english;translate();passed.push('中英切换保留队列和参数');
cancelled=false;let cancellation=applyWorker({w:2000,h:2000,rgba:new Uint8ClampedArray(16000000)},options(false),false);worker.cancel();failed=false;try{await cancellation;}catch{failed=true;}assert(failed,'cancel');cancelled=false;passed.push('取消后台 Worker');
// Known smooth image: rank count 2 against full 1–20 candidate range.
let smooth=new Uint8ClampedArray(96*128*4);for(let y=0;y<128;y++)for(let x=0;x<96;x++){let i=(y*96+x)*4;smooth[i]=x*2;smooth[i+1]=y;smooth[i+2]=(x+y)%256;smooth[i+3]=255;}let scr=transform(new Uint32Array(smooth.buffer),96,128,{Version:1,Algorithm:0,Strength:1,Rounds:2},false),ranks=detectRounds(scr,96,128,1);assert(ranks.slice(0,3).some(c=>c.Rounds===2),'correct count not in top previews');let beforeRounds=$('decrounds').value;await identifyRounds();assert($('roundDialog').open&&$('roundCandidates').querySelectorAll('img').length===3,'candidate previews');assert($('decrounds').value===beforeRounds,'inference silently applied');$('roundDialog').close();passed.push('1–20 次识别、正确次数候选、三幅实际预览、需确认不自动应用');
let invalid=false;try{transform(new Uint32Array(1),1,1,{Version:1,Algorithm:0,Strength:1,Rounds:0},false);}catch{invalid=true;}assert(invalid,'invalid rounds accepted');passed.push('非法次数拒绝');
let zipped=zip(cross);assert(zipped.size>0,'ZIP');let link=document.createElement('a');link.href=URL.createObjectURL(zipped);link.download='web-reference-cross.zip';link.textContent='下载跨端验收样本 ZIP';report.textContent='PASS\n'+passed.join('\n');report.append(document.createElement('br'),link);$('encshift').value=$('decshift').value=1;$('encrounds').value=$('decrounds').value=1;showPreview();renderQueue();
}catch(e){report.textContent='FAIL: '+e.stack;}};
</script>'''
(r/'build/web-check.html').write_text(html.replace('</body>',tests+'</body>'),encoding='utf-8')
large_check=r'''
<section style="background:white;border:3px solid #9078cd;padding:20px"><button id="largeCheck">运行 1200 万像素照片检查</button><pre id="largeReport"></pre></section>
<script>$('largeCheck').onclick=async()=>{let report=$('largeReport');report.textContent='RUNNING';try{let blob=await(await fetch('/build/verification/web-mobile/camera-12mp.jpg')).blob(),item={file:new File([blob],'camera.jpg',{type:'image/jpeg'})};$('encrounds').value=1;$('encshift').value=1;await processItem(item,false);if(item.outputWidth!==4032||item.outputHeight!==3024)throw Error('Photo was resized');let decoded=await decode(item.output,new Uint8Array(await readBlob(item.output)));if(decoded.w!==4032||decoded.h!==3024)throw Error('PNG dimensions changed');report.textContent='PASS: 4032 × 3024 JPEG → Worker → PNG，保持原尺寸';}catch(e){report.textContent='FAIL: '+e.stack;}};</script>
'''
(r/'build/web-check.html').write_text(html.replace('</body>',tests+large_check+'</body>'),encoding='utf-8')
print('Created local-only reference browser checks')
